import{_ as r,C as t,o as a,c,ag as i,E as d}from"./chunks/framework.cyF4XceO.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Takoform","text":"ポータブルな契約。複数の provider。","tagline":"ホスト中立なリソース契約のための Terraform / OpenTofu tooling","actions":[{"theme":"brand","text":"現在の境界を読む","link":"/ja/docs/"},{"theme":"alt","text":"履歴資料を見る","link":"/ja/spec/"}]}},"headers":[],"relativePath":"ja/index.md","filePath":"ja/index.md"}'),s={name:"ja/index.md"};function n(l,e,m,f,_,u){const o=t("StatusNote");return a(),c("div",null,[e[0]||(e[0]=i('<h2 id="stable-host-api-v1-と独立した-version-軸" tabindex="-1">Stable Host API v1 と独立した version 軸 <a class="header-anchor" href="#stable-host-api-v1-と独立した-version-軸" aria-label="Permalink to &quot;Stable Host API v1 と独立した version 軸&quot;">​</a></h2><p>Takoform の Host API <code>forms.takoform.com/v1</code> は、discovery、exact Form availability、lifecycle operation、fence、error を定める stable な wire contract です。Specification 1.0/1.1 の receipt は履歴資料であり、API v1.1、Form の昇格、Provider release を作るものではありません。</p><p>現在の official Form corpus は versionless な一つの family、 <code>edge.forms.takoform.com</code> です。exact な Experimental <code>0.x</code> Form は16個、 Interface は7個、Binding は6個です。正本は <a href="https://github.com/tako0614/takoform-forms/tree/3a395e4d7f9f652a942da52905857fccc41b467e" target="_blank" rel="noreferrer"><code>takoform-forms</code> commit <code>3a395e4</code>（英語のみ）</a> に固定されています。</p><p>Takoform の current version stream は Host API、各 Form definition、Core/library software、Provider software の4つです。Form Package API identifier (<code>packages.forms.takoform.com/v1alpha5</code>) は wire/envelope format であり、5つ目の product version 軸ではありません。</p><table tabindex="0"><thead><tr><th>軸</th><th>現在の identity</th><th>意味</th></tr></thead><tbody><tr><td>Host API</td><td><strong><code>forms.takoform.com/v1</code></strong></td><td>stable wire contract。</td></tr><tr><td>Form</td><td>各 Form の <strong><code>definitionVersion</code></strong></td><td>独立した exact contract。公式 corpus は Edge 16 Forms。</td></tr><tr><td>Core/library</td><td>独立した software SemVer</td><td>SDK、verifier、compiler、CLI の release。</td></tr><tr><td>Provider</td><td>独立した software SemVer</td><td>明示的に対応する official Form の typed tooling。</td></tr></tbody></table><p>canonical Registry の Takoform Provider は official-Forms-only の tool です。第三者 の Form package は同じ Host API path と package/verification contract を使い、自分の namespace と明示的な Provider mapping で配布します。generic carrier や universal infrastructure provider ではありません。一つの Terraform / OpenTofu module で official Takoform Provider と、他の Takoform または industry-standard Provider を組み合わせられます。</p><p>Provider <code>3.0.0</code> は Registry 公開済みの実装ですが、その不変の 8 family / 31 resource projection は Provider release の履歴です。current publisher corpus ではありません。 Edge16 の official-only Provider mapping は次 major の candidate で未公開です。このページ は将来 version の install 可否を主張しません。<code>&gt;=3.1.0</code> を要求する例も release record が公開を示すまでは candidate / unpublished です。</p><h2 id="current-edge-family-16-experimental-forms" tabindex="-1">Current Edge family（16 Experimental Forms） <a class="header-anchor" href="#current-edge-family-16-experimental-forms" aria-label="Permalink to &quot;Current Edge family（16 Experimental Forms）&quot;">​</a></h2><p>詳細ページは現時点ではすべて英語です。リンク名に <strong>（英語のみ）</strong> と明記します。</p><ul><li><a href="/docs/resources/module_worker.html"><code>takoform_module_worker</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_bundle.html"><code>takoform_worker_bundle</code>（英語のみ）</a></li><li><a href="/docs/resources/static_asset_bundle.html"><code>takoform_static_asset_bundle</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_version.html"><code>takoform_worker_version</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_deployment.html"><code>takoform_worker_deployment</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_custom_domain.html"><code>takoform_worker_custom_domain</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_endpoint.html"><code>takoform_worker_endpoint</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_cron_trigger.html"><code>takoform_worker_cron_trigger</code>（英語のみ）</a></li><li><a href="/docs/resources/edge_kv_namespace.html"><code>takoform_edge_kv_namespace</code>（英語のみ）</a></li><li><a href="/docs/resources/sqlite_database.html"><code>takoform_sqlite_database</code>（英語のみ）</a></li><li><a href="/docs/resources/sqlite_migration_set.html"><code>takoform_sqlite_migration_set</code>（英語のみ）</a></li><li><a href="/docs/resources/sqlite_migration_application.html"><code>takoform_sqlite_migration_application</code>（英語のみ）</a></li><li><a href="/docs/resources/at_least_once_queue.html"><code>takoform_at_least_once_queue</code>（英語のみ）</a></li><li><a href="/docs/resources/queue_consumer.html"><code>takoform_queue_consumer</code>（英語のみ）</a></li><li><a href="/docs/resources/durable_workflow.html"><code>takoform_durable_workflow</code>（英語のみ）</a></li><li><a href="/docs/resources/actor_namespace.html"><code>takoform_actor_namespace</code>（英語のみ）</a></li></ul><h2 id="deferred-candidate-source-履歴・保留、英語のみ" tabindex="-1">Deferred candidate source（履歴・保留、英語のみ） <a class="header-anchor" href="#deferred-candidate-source-履歴・保留、英語のみ" aria-label="Permalink to &quot;Deferred candidate source（履歴・保留、英語のみ）&quot;">​</a></h2><p>Function、Container、Table、Pull Queue、Topic、Schedule、Vector の candidate は current ではありません。旧 Provider projection としての source を残していますが、 Current navigation から外し、履歴・保留として扱います。</p><ul><li>Function: <code>takoform_function</code>, <code>takoform_function_version</code>, <code>takoform_function_deployment</code>, <code>takoform_function_endpoint</code></li><li>Container: <code>takoform_serverless_container_service</code>, <code>takoform_container_revision</code>, <code>takoform_container_traffic</code>, <code>takoform_container_endpoint</code>, <code>takoform_container_custom_domain</code></li><li>Table / Pull Queue: <code>takoform_table</code>, <code>takoform_pull_queue</code></li><li>Topic: <code>takoform_topic</code>, <code>takoform_topic_subscription</code></li><li>Schedule / Vector: <code>takoform_message_schedule</code>, <code>takoform_dense_vector_index</code></li></ul><p>これらのページは英語のみの履歴資料であり、削除せず source history として保持します。</p><h2 id="履歴資料" tabindex="-1">履歴資料 <a class="header-anchor" href="#履歴資料" aria-label="Permalink to &quot;履歴資料&quot;">​</a></h2><p>撤回された Host API epoch、Specification receipt、Provider 1/2 release は exact pin による recovery / migration のための履歴です。現在の version lane ではありません。 <a href="/release/">履歴 release</a> と <a href="/release/migrations/v2-to-v3.html">v2 から v3 への移行境界</a>（英語のみ）を参照してください。</p>',16)),d(o)])}const k=r(s,[["render",n]]);export{h as __pageData,k as default};
